	; BDIR (bit 7) and BC1 (bit 6) lines (&C0 = select register, &40 =
	; read it), and the AY's port A (register 14) returns the 8 column bits,
	; 0 = pressed. Row 9 is joystick 0 (and DEL). A firmware key
	; number is row * 8 + bit.
